const fs = require('fs')
const path = require('path')

module.exports = safety_backup

// before every apply: the old value of each changed key + a full `dconf dump /` for manual recovery
function safety_backup ({ dir, dconf }) {
  const api = { save, list, rollback }
  return api

  // changes: [{ key, local, remote }], local is the value before the apply (null = not set)
  async function save (changes) {
    await fs.promises.mkdir(dir, { recursive: true })
    const id = new Date().toISOString().replace(/[:.]/g, '-')
    await fs.promises.writeFile(path.join(dir, id + '.dconf'), await dconf.dump('/'))
    await fs.promises.writeFile(path.join(dir, id + '.json'), JSON.stringify({ id, changes }, null, 2))
    return id
  }

  async function list () {
    const files = await fs.promises.readdir(dir).catch(() => [])
    return files.filter(file => file.endsWith('.json')).map(file => file.slice(0, -5)).sort()
  }

  // puts back the old values of one backup (the newest by default), returns the restored changes
  async function rollback (id) {
    id = id || (await list()).pop()
    if (!id) throw new Error('no backups yet')
    const { changes } = JSON.parse(await fs.promises.readFile(path.join(dir, id + '.json'), 'utf8'))
    for (const change of changes.slice().reverse()) await restore({ dconf, change })
    return changes
  }
}

function restore ({ dconf, change }) {
  return change.local === null ? dconf.reset(change.key) : dconf.write(change.key, change.local)
}
